const test = require('node:test');
const assert = require('node:assert/strict');
const { redeem } = require('../src/codes');

test('two concurrent redemptions: exactly one succeeds', async () => {
  const results = await Promise.all([redeem('SAVE10', 'c-1'), redeem('SAVE10', 'c-1')]);
  assert.deepEqual(results.map((r) => r.ok).sort(), [false, true]);
});
